argv:
query=query($owner: String!, $repo: String!, $b0: String!, $b1: String!, $b2: String!) {
  repository(owner: $owner, name: $repo) {
    b0: pullRequests(headRefName: $b0, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { number url body state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } commits(last: 1) { nodes { commit { statusCheckRollup { state } } } } } }
    b1: pullRequests(headRefName: $b1, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { number url body state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } commits(last: 1) { nodes { commit { statusCheckRollup { state } } } } } }
    b2: pullRequests(headRefName: $b2, first: 1, orderBy: {field: CREATED_AT, direction: DESC}) { nodes { number url body state mergedAt timelineItems(last: 1, itemTypes: [CLOSED_EVENT]) { nodes { ... on ClosedEvent { actor { login } } } } commits(last: 1) { nodes { commit { statusCheckRollup { state } } } } } }
  }
}
